// Category B — a chart: a line, bar or donut over categories, with its title, a legend and the same
// data as a table: hourly sales against a comparison day, channel shares, visits per segment.
//
// It composes Recharts, a complete library themed through tokens.
// Recharts draws; the look is this component's Cmp tokens, passed to Recharts as CSS custom
// properties, so a brand restyles a chart the way it restyles a Button.
//
// Colour is never the only cue (sys-tokens.md § chart: the series share one lightness). Each line
// series has its own stroke pattern, none shared, which the legend draws again as its mark; a
// comparison series has its own dash in the neutral ink; bars follow the legend's order; donut slices carry
// direct percentage labels. The table carries every number.
//
// The plot is hidden from assistive technology and the same numbers are a table in the figure, read
// in its place: a screen reader cannot read a drawing, and a table is the form a person can navigate.
// The table is visually hidden; `showTable` shows it, for a page that offers "표로 보기".
//
// Recharts' own keyboard layer is off (`accessibilityLayer={false}`): the plot is aria-hidden, and a
// focusable element inside it would be a stop with no name. The table is the accessible form.
//
// Motion: series draw in only when the person has not asked for reduced motion.
import { useCallback, useId } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import type { Ref } from "react";
import { useReducedMotion } from "./useReducedMotion";
import "./Chart.css";

export interface ChartSeries {
  /** Stable key. */
  id: string;
  /** The series' name, in the legend and the table header, e.g. "오늘". */
  label: string;
  /** One value per category, in the categories' order. */
  values: number[];
  /** A comparison series (e.g. last week): drawn dashed in the neutral ink, after the others. */
  isComparison?: boolean;
}

export interface ChartProps {
  /**
   * Size axis: the plot height.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /**
   * `line` and `bar` plot every series over the categories; `donut` shares the first series' values
   * out across the categories.
   */
  type: "line" | "bar" | "donut";
  /** The chart's title: the figure caption and the table caption. */
  title: string;
  /** The x-axis labels, or the donut's slice names. */
  categories: string[];
  /** The series. A donut reads only the first. */
  series: ChartSeries[];
  /** Formats a value for the axis, the tooltip and the table, e.g. `(v) => \`${v.toLocaleString()}원\``. */
  formatValue?: (value: number) => string;
  /** When true, bars stack instead of standing side by side. */
  isStacked?: boolean;
  /** When true the data table shows under the plot instead of only to assistive technology. */
  showTable?: boolean;
  /** Additional class (optional). sd-chart is always preserved. */
  className?: string;
  /** Forwarded to the figure element. */
  ref?: Ref<HTMLElement>;
}

// One stroke pattern per series, so no two lines share a pattern; the comparison's is its own. Eight
// patterns for the eight chart colours: a chart with more series repeats both, and is too many to read.
const DASHES = ["", "2 3", "8 3", "10 3 2 3", "1 5", "14 4", "4 2 1 2", "6 2 2 2 2 2"];
const COMPARISON_DASH = "6 4";
const CATEGORY = "__category";
const key = (s: ChartSeries) => `series:${s.id}`;
const SERIES_INK = [
  "var(--sd-chart-series-1)",
  "var(--sd-chart-series-2)",
  "var(--sd-chart-series-3)",
  "var(--sd-chart-series-4)",
  "var(--sd-chart-series-5)",
  "var(--sd-chart-series-6)",
  "var(--sd-chart-series-7)",
  "var(--sd-chart-series-8)",
];
const color = (i: number) => SERIES_INK[i % SERIES_INK.length];

export function Chart({
  size = "medium",
  type,
  title,
  categories,
  series,
  formatValue = (v) => v.toLocaleString(),
  isStacked = false,
  showTable = false,
  className,
  ref,
}: ChartProps) {
  const captionId = useId();
  const animate = !useReducedMotion();
  // Category and series live under keys no series id can take.
  const rows = categories.map((c, i) => ({ [CATEGORY]: c, ...Object.fromEntries(series.map((s) => [key(s), s.values[i]])) }));
  const ordered = [...series.filter((s) => !s.isComparison), ...series.filter((s) => s.isComparison)];
  const ink = (s: ChartSeries, i: number) => (s.isComparison ? "var(--sd-chart-comparison)" : color(i));
  const dash = (s: ChartSeries, i: number) => (s.isComparison ? COMPARISON_DASH : DASHES[i % DASHES.length]);
  const attach = useCallback(
    (el: HTMLElement | null) => {
      // React 19 stores a callback ref's returned cleanup; hand the caller's back.
      if (typeof ref === "function") return ref(el);
      if (ref) ref.current = el;
    },
    [ref],
  );
  const axis = { stroke: "var(--sd-chart-grid)", tick: { fill: "var(--sd-chart-axis-foreground)" } };
  const tooltip = (
    <Tooltip
      formatter={(v) => formatValue(Number(v))}
      wrapperClassName="sd-chart__tooltip"
      contentStyle={{ background: "transparent", border: "none", padding: 0 }}
      cursor={{ stroke: "var(--sd-chart-grid)", fill: "var(--sd-chart-cursor)" }}
    />
  );
  const total = series[0]?.values.reduce((a, b) => a + b, 0) ?? 0;

  return (
    <figure
      ref={attach}
      aria-labelledby={captionId}
      className={className ? `sd-chart ${className}` : "sd-chart"}
    >
      <figcaption id={captionId} className="sd-chart__title sd-type-label-medium-emphasized">
        {title}
      </figcaption>
      <div className="sd-chart__plot sd-type-caption-medium" data-size={size} aria-hidden="true">
        <ResponsiveContainer width="100%" height="100%">
          {type === "line" ? (
            <LineChart data={rows} accessibilityLayer={false}>
              <CartesianGrid vertical={false} stroke="var(--sd-chart-grid)" />
              <XAxis dataKey={CATEGORY} {...axis} tickLine={false} />
              <YAxis {...axis} tickLine={false} axisLine={false} tickFormatter={formatValue} width="auto" />
              {tooltip}
              {ordered.map((s, i) => (
                <Line
                  key={s.id}
                  dataKey={key(s)}
                  name={s.label}
                  type="monotone"
                  stroke={ink(s, i)}
                  strokeWidth="var(--sd-chart-line-width)"
                  strokeDasharray={dash(s, i) || undefined}
                  dot={false}
                  isAnimationActive={animate}
                />
              ))}
            </LineChart>
          ) : type === "bar" ? (
            <BarChart data={rows} accessibilityLayer={false}>
              <CartesianGrid vertical={false} stroke="var(--sd-chart-grid)" />
              <XAxis dataKey={CATEGORY} {...axis} tickLine={false} />
              <YAxis {...axis} tickLine={false} axisLine={false} tickFormatter={formatValue} width="auto" />
              {tooltip}
              {ordered.map((s, i) => (
                <Bar
                  key={s.id}
                  dataKey={key(s)}
                  name={s.label}
                  stackId={isStacked ? "stack" : undefined}
                  fill={ink(s, i)}
                  // The corner is CSS (a clip-path from chart.bar.radius), so a theme switch anywhere above
                  // restyles it without a re-render. Only the end away from the axis rounds; a stacked bar
                  // stays square.
                  shape={(props: { x?: number; y?: number; width?: number; height?: number; fill?: string }) => (
                    // A negative value arrives as a negative height below y: SVG draws no rect with a
                    // negative height, so the rect is normalised to start at the lower edge.
                    <rect
                      className="sd-chart__bar"
                      data-stacked={isStacked || undefined}
                      data-negative={(props.height ?? 0) < 0 || undefined}
                      x={props.x}
                      y={(props.height ?? 0) < 0 ? (props.y ?? 0) + (props.height ?? 0) : props.y}
                      width={props.width}
                      height={Math.abs(props.height ?? 0)}
                      fill={props.fill}
                    />
                  )}
                  isAnimationActive={animate}
                />
              ))}
            </BarChart>
          ) : (
            <PieChart accessibilityLayer={false}>
              {tooltip}
              <Pie
                data={rows}
                dataKey={series[0] ? key(series[0]) : ""}
                nameKey={CATEGORY}
                // The ring leaves room around it for the direct labels Recharts sets outside it. A very long
                // category name in a narrow figure can still reach the edge; the legend and table keep it.
                innerRadius="40%"
                outerRadius="62%"
                paddingAngle={1}
                stroke="var(--sd-chart-slice-gap)"
                // Direct labels in the axis ink, not the slice's: the name and share, so colour is not the cue.
                label={({ x, y, textAnchor, name, percent }) => (
                  <text x={x} y={y} textAnchor={textAnchor} dominantBaseline="central" fill="var(--sd-chart-axis-foreground)">
                    {`${name} ${Math.round((percent ?? 0) * 100)}%`}
                  </text>
                )}
                labelLine={false}
                rootTabIndex={-1}
                isAnimationActive={animate}
              >
                {categories.map((c, i) => (
                  <Cell key={c} fill={color(i)} />
                ))}
              </Pie>
            </PieChart>
          )}
        </ResponsiveContainer>
      </div>
      <ul className="sd-chart__legend sd-type-caption-medium" aria-hidden="true">
        {(type === "donut"
          ? categories.map((c, i) => ({ id: c, label: c, ink: color(i), dash: null }))
          : ordered.map((s, i) => ({ id: s.id, label: s.label, ink: ink(s, i), dash: type === "bar" ? null : dash(s, i) }))
        ).map((l) => (
          <li key={l.id} className="sd-chart__legend-item">
            {l.dash === null ? (
              <span className="sd-chart__swatch" style={{ color: l.ink }} />
            ) : (
              // The mark repeats the series' own stroke pattern.
              <svg className="sd-chart__mark" viewBox="0 0 24 4" preserveAspectRatio="none">
                <line x1="0" y1="2" x2="24" y2="2" stroke={l.ink} strokeWidth="var(--sd-chart-line-width)" strokeDasharray={l.dash || undefined} vectorEffect="non-scaling-stroke" />
              </svg>
            )}
            {l.label}
          </li>
        ))}
      </ul>
      <table className={showTable ? "sd-chart__table sd-type-caption-medium" : "sd-visually-hidden"}>
        <caption>{title}</caption>
        <thead>
          <tr>
            <td />
            {(type === "donut" ? series.slice(0, 1) : ordered).map((s) => (
              <th key={s.id} scope="col">{s.label}</th>
            ))}
            {type === "donut" && <th scope="col">%</th>}
          </tr>
        </thead>
        <tbody>
          {categories.map((c, i) => (
            <tr key={c}>
              <th scope="row">{c}</th>
              {(type === "donut" ? series.slice(0, 1) : ordered).map((s) => (
                <td key={s.id}>{formatValue(s.values[i] ?? 0)}</td>
              ))}
              {type === "donut" && <td>{total ? Math.round(((series[0]?.values[i] ?? 0) / total) * 100) : 0}%</td>}
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  );
}

/* A figure: the title, the plot, the legend and the table. Recharts draws the plot and reads its
   colours, widths and type through the custom properties below; every other part is laid out here. */
.sd-chart {
  display: flex;
  flex-direction: column;
  gap: var(--sd-chart-gap);
  margin: 0;
  min-inline-size: 0;
  color: var(--sd-chart-foreground);
  --sd-chart-text-padding-inline-current: var(--sd-chart-text-padding-inline);
}

/* A bar or donut legend leads with a rounded swatch on the title's start edge in the same column, so
   the title takes the text inset there (component-contract.md §6 rule 8, component-owned text).
   Inline only. */
.sd-chart__title {
  padding-inline: var(--sd-chart-text-padding-inline-current);
}

.sd-chart__plot {
  inline-size: 100%;
  /* The plot is a drawing: its role class sizes the axis labels and must not pad the svg. */
  padding-inline: 0;
}
.sd-chart__plot[data-size="small"] {
  block-size: var(--sd-chart-height-small);
}
.sd-chart__plot[data-size="medium"] {
  block-size: var(--sd-chart-height-medium);
}
.sd-chart__plot[data-size="large"] {
  block-size: var(--sd-chart-height-large);
}

.sd-chart__legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sd-chart-legend-gap);
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--sd-chart-axis-foreground);
}

.sd-chart__legend-item {
  display: inline-flex;
  align-items: center;
  gap: var(--sd-chart-legend-item-gap);
}

/* The legend mark: a line series draws its own stroke pattern (an inline SVG); a bar or slice a square
   of its fill. */
.sd-chart__mark {
  inline-size: var(--sd-chart-swatch-length);
  block-size: var(--sd-chart-line-width);
  overflow: visible;
}

.sd-chart__swatch {
  display: inline-block;
  inline-size: var(--sd-chart-swatch-size);
  block-size: var(--sd-chart-swatch-size);
  border-radius: var(--sd-chart-swatch-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: currentColor;
}

.sd-chart__tooltip {
  padding: var(--sd-chart-tooltip-padding);
  border: var(--sd-chart-tooltip-border-width) solid var(--sd-chart-tooltip-border);
  border-radius: var(--sd-chart-tooltip-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-chart-tooltip-background);
  color: var(--sd-chart-tooltip-foreground);
}

.sd-chart__table {
  border-collapse: collapse;
  text-align: end;
  font-variant-numeric: tabular-nums;
}

/* A bar's corners: the end away from the axis rounds, the foot on the axis stays square. A clip-path, so the token applies through CSS and follows a theme switch at once. */
.sd-chart__bar {
  clip-path: inset(0 round var(--sd-chart-bar-radius) var(--sd-chart-bar-radius) 0 0);
}
.sd-chart__bar[data-negative] {
  clip-path: inset(0 round 0 0 var(--sd-chart-bar-radius) var(--sd-chart-bar-radius));
}
.sd-chart__bar[data-stacked] {
  clip-path: none;
}
